package local.morphtv.legacy;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.Build;import android.widget.Toast;import java.io.*;import java.net.*;import java.security.*;import javax.net.ssl.*;import org.json.*;
/** One verified updater shared by both API19 products. No playback code is involved. */
final class LegacyUpdate {
 private static volatile boolean busy,pending;private static boolean arabic;
 private static String text(String ar,String en){return arabic?ar:en;}
 private static HttpURLConnection get(String name)throws Exception{HttpsURLConnection c=(HttpsURLConnection)new URL("https://morph-tv.com/"+name).openConnection();if(Build.VERSION.SDK_INT<21){SSLContext tls=SSLContext.getInstance("TLSv1.2");tls.init(null,null,null);c.setSSLSocketFactory(tls.getSocketFactory());}c.setRequestProperty("User-Agent","MorphTV/Updates");c.setRequestProperty("Accept-Encoding","identity");c.setInstanceFollowRedirects(false);c.setConnectTimeout(10000);c.setReadTimeout(20000);if(c.getResponseCode()!=200){c.disconnect();throw new IOException("Update unavailable");}return c;}
 private static String prefix(Activity a){return a.getPackageName().equals("local.morph.iptv.legacy")?"Morph-IPTV-Legacy-":"Morph-TV-Legacy-";}
 private static int compare(String a,String b)throws Exception{if(!a.matches("[0-9]+\\.[0-9]+\\.[0-9]+")||!b.matches("[0-9]+\\.[0-9]+\\.[0-9]+"))throw new IOException("Invalid version");String[] x=a.split("\\."),y=b.split("\\.");for(int i=0;i<3;i++){long u=Long.parseLong(x[i]),v=Long.parseLong(y[i]);if(u!=v)return u<v?-1:1;}return 0;}
 static synchronized void check(final Activity a,boolean ar){if(busy)return;busy=true;arabic=ar;final ProgressDialog progress=new ProgressDialog(a);progress.setTitle(text("تحديث التطبيق","App update"));progress.setMessage(text("جاري فحص التحديث…","Checking update…"));progress.setCancelable(false);progress.show();new Thread(new Runnable(){public void run(){try{HttpURLConnection c=get("catalog.json");JSONObject catalog;try{ByteArrayOutputStream out=new ByteArrayOutputStream();InputStream in=c.getInputStream();try{byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>524288)throw new IOException("Catalog too large");out.write(buffer,0,n);}}finally{in.close();}catalog=new JSONObject(out.toString("UTF-8"));}finally{c.disconnect();}String installed=a.getPackageManager().getPackageInfo(a.getPackageName(),0).versionName;JSONArray all=catalog.getJSONArray("releases");JSONObject best=null;for(int i=0;i<all.length();i++){JSONObject row=all.getJSONObject(i);String version=row.optString("version");if(!version.matches("[0-9]+\\.[0-9]+\\.[0-9]+")||!row.optString("file").equals(prefix(a)+version+".apk"))continue;if(!row.optString("sha256").matches("[a-f0-9]{64}")||row.optLong("bytes")<10000||row.optLong("bytes")>33554432)continue;if(best==null||compare(version,best.getString("version"))>0)best=row;}if(best==null)throw new IOException("No compatible release");if(compare(best.getString("version"),installed)<=0){a.runOnUiThread(new Runnable(){public void run(){message(a,text("أنت تستخدم أحدث إصدار متاح.","You have the latest available version."));}});return;}download(a,best,progress);}catch(Exception e){a.runOnUiThread(new Runnable(){public void run(){message(a,text("تعذر فحص أو تحميل تحديث موثوق. تحقق من الإنترنت والمساحة. قد لا يدعم هذا الجهاز اتصال HTTPS المطلوب.","Could not check or download a verified update. Check Internet and storage. This device may not support the required HTTPS connection."));}});}finally{busy=false;a.runOnUiThread(new Runnable(){public void run(){if(progress.isShowing())progress.dismiss();}});}}},"morph-legacy-update").start();}
 private static void download(final Activity a,JSONObject row,final ProgressDialog progress)throws Exception{final long expected=row.getLong("bytes");a.runOnUiThread(new Runnable(){public void run(){progress.setMessage(text("جاري تحميل التحديث…","Downloading update…"));}});File partial=new File(a.getCacheDir(),"legacy-update.partial");HttpURLConnection c=null;try{c=get(row.getString("file"));MessageDigest hash=MessageDigest.getInstance("SHA-256");long total=0,deadline=System.nanoTime()+300000000000L;InputStream in=c.getInputStream();try{OutputStream out=new FileOutputStream(partial);try{byte[] b=new byte[32768];int n;while((n=in.read(b))!=-1){if(System.nanoTime()>deadline||(total+=n)>expected)throw new IOException("Update size rejected");out.write(b,0,n);hash.update(b,0,n);}}finally{out.close();}}finally{in.close();}StringBuilder actual=new StringBuilder();for(byte b:hash.digest())actual.append(String.format(java.util.Locale.US,"%02x",b&255));if(total!=expected||!actual.toString().equals(row.getString("sha256")))throw new IOException("Update checksum rejected");PackageManager pm=a.getPackageManager();PackageInfo own=pm.getPackageInfo(a.getPackageName(),PackageManager.GET_SIGNATURES),apk=pm.getPackageArchiveInfo(partial.getAbsolutePath(),PackageManager.GET_SIGNATURES);if(apk==null||!a.getPackageName().equals(apk.packageName)||apk.versionCode<=own.versionCode||!row.getString("version").equals(apk.versionName)||apk.signatures==null||own.signatures==null||apk.signatures.length!=1||own.signatures.length!=1||!apk.signatures[0].equals(own.signatures[0]))throw new IOException("Update identity rejected");File target=new File(a.getCacheDir(),"verified-legacy-update.apk");if(target.exists()&&!target.delete()||!partial.renameTo(target))throw new IOException("Could not stage update");a.runOnUiThread(new Runnable(){public void run(){if(!a.isFinishing()){pending=true;prompt(a);}}});}finally{partial.delete();if(c!=null)c.disconnect();}}
 private static boolean allowed(Activity a){if(Build.VERSION.SDK_INT<26)return android.provider.Settings.Secure.getInt(a.getContentResolver(),"install_non_market_apps",0)==1;try{return Boolean.TRUE.equals(PackageManager.class.getMethod("canRequestPackageInstalls").invoke(a.getPackageManager()));}catch(Exception e){return false;}}
 static void resume(Activity a){if(pending&&allowed(a))prompt(a);}
 private static void prompt(final Activity a){if(!pending||a.isFinishing())return;if(!allowed(a)){new AlertDialog.Builder(a).setTitle(text("السماح بتحديث التطبيق","Allow app updates")).setMessage(text("اسمح بتثبيت تحديثات التطبيق من إعدادات أندرويد، ثم ارجع لإكمال التحديث.","Allow app updates in Android settings, then return to finish the update.")).setPositiveButton(text("فتح الإعدادات","Open settings"),new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){try{a.startActivity(Build.VERSION.SDK_INT>=26?new Intent("android.settings.MANAGE_UNKNOWN_APP_SOURCES",Uri.parse("package:"+a.getPackageName())):new Intent(android.provider.Settings.ACTION_SECURITY_SETTINGS));}catch(Exception e){pending=false;}}}).setNegativeButton(text("إلغاء","Cancel"),new DialogInterface.OnClickListener(){public void onClick(DialogInterface d,int n){pending=false;}}).show();return;}pending=false;try{a.startActivity(new Intent(Intent.ACTION_VIEW).setDataAndType(Uri.parse("content://"+a.getPackageName()+".updates/update.apk"),"application/vnd.android.package-archive").addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION));}catch(Exception e){message(a,text("تعذر فتح مثبّت أندرويد.","Could not open the Android installer."));}}
 private static void message(Activity a,String value){if(!a.isFinishing())new AlertDialog.Builder(a).setTitle("Morph").setMessage(value).setPositiveButton("OK",null).show();}
}
